//! The compiler checks the parser library states: every source of the table against the byte ranges the pinned Ruff 0.16.5
//! reports as invalid syntax for it at Python 3.10 (`ruff check --isolated --target-version py310`, generated by
//! parity-a/probes/syntax/gen.py), each in a module and in a stub.

use super::fixtures::diagnostics::diagnostics;
use crate::outbound::syntax::types::PythonSourceKind;

/// A case's name, its source, and the reference's ranges.
type Row = (&'static str, &'static str, &'static [(u32, u32)]);

/// The reference table.
const TABLE: &[Row] = &[
    (
        "wildcard_before_another_case",
        "match value:\n    case _:\n        pass\n    case 1:\n        pass\n",
        &[(22, 23)],
    ),
    (
        "capture_before_another_case",
        "match value:\n    case irrefutable:\n        pass\n    case 1:\n        pass\n",
        &[(22, 33)],
    ),
    (
        "capture_alias_before_another_case",
        "match value:\n    case first as second:\n        pass\n    case 1:\n        pass\n",
        &[(22, 27)],
    ),
    (
        "capture_in_or_before_another_case",
        "match value:\n    case 1 | other:\n        pass\n    case 2:\n        pass\n",
        &[(22, 31), (26, 31)],
    ),
    (
        "capture_as_last_case",
        "match value:\n    case 1:\n        pass\n    case other:\n        pass\n",
        &[],
    ),
    (
        "guarded_capture_before_another_case",
        "match value:\n    case other if other:\n        pass\n    case 1:\n        pass\n",
        &[],
    ),
    (
        "duplicate_mapping_key",
        "match x:\n    case {'key': 1, 'key': 2}:\n        pass\n",
        &[(29, 34)],
    ),
    (
        "duplicate_class_attribute",
        "match x:\n    case Point(x=1, x=2):\n        pass\n",
        &[(29, 30)],
    ),
    (
        "name_bound_twice",
        "match x:\n    case [a, a]:\n        pass\n",
        &[(22, 23)],
    ),
    (
        "name_bound_twice_in_mapping_rest",
        "match x:\n    case {'k': a, **a}:\n        pass\n",
        &[(29, 30)],
    ),
    (
        "starred_return",
        "def func():\n    return *x\n",
        &[(23, 25)],
    ),
    (
        "starred_for_target",
        "for *x in range(10):\n    pass\n",
        &[(4, 6)],
    ),
    ("starred_yield", "def func():\n    yield *x\n", &[(22, 24)]),
    (
        "starred_in_tuple_return",
        "def func():\n    return (*x,)\n",
        &[],
    ),
    (
        "async_comprehension_in_sync_comprehension",
        "async def f(): return [[x async for x in foo(n)] for n in range(3)]\n",
        &[(26, 47)],
    ),
    (
        "async_comprehension_in_async_comprehension",
        "async def test(): return [[x async for x in elements(n)] async for n in range(3)]\n",
        &[],
    ),
    (
        "async_comprehension_after_sync_comprehension",
        "async def f():\n    [_ for n in range(3)]\n    [_ async for n in range(3)]\n",
        &[],
    ),
    (
        "async_comprehension_in_function_in_sync_comprehension",
        "async def f():\n    [lambda: [x async for x in y] for n in z]\n",
        &[(31, 47)],
    ),
];

#[test]
fn every_source_reports_the_reference_ranges() {
    assert!(TABLE.len() >= 18, "the table stays whole");
    for (name, source, expected) in TABLE {
        for kind in [PythonSourceKind::Python, PythonSourceKind::Stub] {
            let found: Vec<(u32, u32)> = diagnostics(source, kind)
                .into_iter()
                .map(|(_, _, _, start, end)| (start, end))
                .collect();
            assert_eq!(found, expected.to_vec(), "{name} ({kind:?})");
        }
    }
}
